/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.update = async function () {
    /* sdd-asis-lifecycle:begin fn_Update — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await scwin.chkData()) {
        return false;
    }
    scwin.setCellphoneNoEtc();
    const SendForm = (document.SendForm || { elements: [] });
    if (await $c.win.confirm("변경하시겠습니까?")) {
        const addNew = $c.util.getComponent('ipt_addNew').getValue();
        if (addNew === "ADD") {
            /* 수동 전환 필요: 이름 선택자 순회 [name=doc_bdchrg_tp_cd] — B4 반복 밖 동명 입력(정적/계수 틀) · to-be 에 돌 요소가 없다 */ $("input[name='doc_bdchrg_tp_cd']").each(function(index) {
                    $(this).val($c.util.getComponent('slc_bdchrgTpCd').getValue());
            });
            scwin.form_SendForm.action = "/register/registerNew.do?method=changeBdchrg";
        } else {
            scwin.form_SendForm.action = "/register/registerNew.do?method=updateBdchrgInfo";
        }
        scwin.form_SendForm.target = "_self";
        await scwin.tx_fn_Update();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getChrgNm
 * @author Inswave
